content.css:
.insight {
  position: absolute;
  inset: 3px 4px 6px 3px;
  box-sizing: border-box;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid #1E3A8A;
  background: radial-gradient(140% 90% at 100% 0%, rgba(34, 211, 238, 0.16) 0%, transparent 60%), #0F1E3D;
  box-shadow: 0 6px 18px rgba(15, 30, 61, 0.35);
  color: #FFFFFF;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  overflow: hidden;
}
.insight.novo .insight-titulo {
  animation: insight-entrada 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.insight.novo .insight-texto {
  animation: insight-entrada 0.5s 0.12s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.insight-rotulo {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  margin-bottom: 6px;
}
.insight-titulo {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.22;
  margin-bottom: 8px;
}
.insight-texto {
  font-size: 11.5px;
  line-height: 1.45;
  color: #CBD5E1;
}
@keyframes insight-entrada {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .insight * {
    animation: none !important;
  }
}
